import type { Room } from "@colyseus/sdk";

/**
 * Development only (`npm run dev`; main.ts imports this module only when `import.meta.env.DEV`, so the production
 * build does not contain it): delays everything a room's socket sends and receives, the server's round-trip probes
 * and Colyseus's own pings included, by half of `rttMs` each way plus a uniform ±jitter/2, never reordering. It lets
 * the operator playtest §19's latencies on one machine: `?rtt=80&jitter=20`.
 */
export const DEV_LATENCY_MARKER = "pirate-sea-race dev latency";

export interface DevLatency {
  readonly rttMs: number;
  readonly jitterMs: number;
}

/** The setting from the page's query string, or undefined when it asks for none. */
export function devLatencyFromQuery(search: string): DevLatency | undefined {
  const query = new URLSearchParams(search);
  const rttMs = Number(query.get("rtt") ?? 0);
  const jitterMs = Number(query.get("jitter") ?? 0);
  if (!(rttMs > 0 || jitterMs > 0) || !Number.isFinite(rttMs) || !Number.isFinite(jitterMs)) return undefined;
  return { rttMs: Math.max(0, rttMs), jitterMs: Math.max(0, jitterMs) };
}

/** An ordered delay line: each item leaves at the later of its own time and the previous item's. */
class DelayLine {
  private last = 0;

  constructor(private readonly latency: DevLatency) {}

  push(deliver: () => void): void {
    const delay = Math.max(0, this.latency.rttMs / 2 + (Math.random() - 0.5) * this.latency.jitterMs);
    const at = Math.max(this.last, performance.now() + delay);
    this.last = at;
    setTimeout(deliver, at - performance.now());
  }
}

/** Wraps a joined room's connection in both directions. It survives the SDK's reconnection, which reuses both hooks. */
export function applyDevLatency(room: Room, latency: DevLatency): void {
  console.info(`${DEV_LATENCY_MARKER}: ${latency.rttMs} ms round trip, ${latency.jitterMs} ms jitter`);
  const connection = room.connection as unknown as {
    transport: { send(data: Uint8Array): void };
    events: { onmessage?: (event: unknown) => void };
  };
  const outgoing = new DelayLine(latency);
  const send = connection.transport.send.bind(connection.transport);
  connection.transport.send = (data: Uint8Array) => {
    const copy = new Uint8Array(data);
    outgoing.push(() => {
      try {
        send(copy);
      } catch {
        // The socket closed meanwhile; a real network would have lost it too.
      }
    });
  };
  const incoming = new DelayLine(latency);
  const receive = connection.events.onmessage;
  connection.events.onmessage = (event: unknown) => incoming.push(() => receive?.call(connection.events, event));
}
import { describe, expect, it } from "vitest";
import { DUEL_INPUT } from "@pirate-sea-race/content/moves";
import { devLatencyFromQuery } from "./devLatency.js";
import { resultText, roundClock } from "./duelHud.js";
import { duelBits, DuelKeyboard } from "./duelKeyboard.js";

describe("duel keyboard", () => {
  it("maps §8's keys: WASD or arrows, J, K, U, I and Shift", () => {
    expect(duelBits(["KeyA", "ArrowRight", "KeyW", "ArrowDown"])).toBe(DUEL_INPUT.left | DUEL_INPUT.right | DUEL_INPUT.up | DUEL_INPUT.down);
    expect(duelBits(["KeyJ", "KeyK", "KeyU", "KeyI", "ShiftRight"])).toBe(
      DUEL_INPUT.light | DUEL_INPUT.heavy | DUEL_INPUT.special1 | DUEL_INPUT.special2 | DUEL_INPUT.dash,
    );
    expect(duelBits(["KeyE", "Space"])).toBe(0);
  });

  it("keeps a tap released before any frame was tagged until one is", () => {
    const keyboard = new DuelKeyboard(new EventTarget() as unknown as Window);
    keyboard.press("KeyJ");
    keyboard.release("KeyJ");
    expect(keyboard.bits()).toBe(DUEL_INPUT.light);
    expect(keyboard.bits()).toBe(DUEL_INPUT.light);
    keyboard.framesTagged();
    expect(keyboard.bits()).toBe(0);
    // A held key stays in after the frame that took it.
    keyboard.press("KeyD");
    keyboard.framesTagged();
    expect(keyboard.bits()).toBe(DUEL_INPUT.right);
  });
});

describe("duel HUD", () => {
  it("counts the round clock down to 0 on the round's last frame, then shows overtime", () => {
    expect(roundClock(0, 3600, 600)).toEqual({ seconds: 60, overtime: false });
    expect(roundClock(3599, 3600, 600)).toEqual({ seconds: 1, overtime: false });
    expect(roundClock(3600, 3600, 600)).toEqual({ seconds: 0, overtime: false });
    expect(roundClock(3601, 3600, 600)).toEqual({ seconds: 10, overtime: true });
    expect(roundClock(4200, 3600, 600)).toEqual({ seconds: 0, overtime: true });
  });

  it("words the result", () => {
    expect(resultText(0, "timeout")).toBe("Player 1 wins by time");
    expect(resultText(1, "forfeit")).toBe("Player 2 wins by forfeit");
    expect(resultText(-1, "double-ko")).toBe("Draw (double KO)");
  });
});

describe("dev latency setting", () => {
  it("reads a round trip and jitter from the query string, and nothing otherwise", () => {
    expect(devLatencyFromQuery("?rtt=80&jitter=20")).toEqual({ rttMs: 80, jitterMs: 20 });
    expect(devLatencyFromQuery("?rtt=150")).toEqual({ rttMs: 150, jitterMs: 0 });
    expect(devLatencyFromQuery("")).toBeUndefined();
    expect(devLatencyFromQuery("?rtt=abc")).toBeUndefined();
  });
});
import { Client, type Room } from "@colyseus/sdk";
import { CREATE_TOKEN_BYTES, DUEL_ROOM, formatCreateToken, normalizeMatchCode, PROTOCOL_VERSION } from "@pirate-sea-race/protocol";
import type { DuelRoomStateSchema } from "@pirate-sea-race/server/schema";

export type DuelRoom = Room<unknown, DuelRoomStateSchema>;

/** Creates a duel (or a practice duel against the server's dummy) with a fresh one-time token. */
export function createDuel(endpoint: string, practice: boolean): Promise<DuelRoom> {
  const createToken = formatCreateToken(crypto.getRandomValues(new Uint8Array(CREATE_TOKEN_BYTES)));
  return new Client(endpoint).create<DuelRoomStateSchema>(DUEL_ROOM, {
    protocolVersion: PROTOCOL_VERSION,
    createToken,
    ...(practice ? { practice: true } : {}),
  });
}

export function joinDuel(endpoint: string, code: string): Promise<DuelRoom> {
  return new Client(endpoint).join<DuelRoomStateSchema>(DUEL_ROOM, { protocolVersion: PROTOCOL_VERSION, code: normalizeMatchCode(code) });
}

