  type DuelRoomPhase,
  type DummyBehaviour,
} from "@pirate-sea-race/protocol";
import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
import { DuelClientSession, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
import type { ArenaSource } from "./arenaScene.js";
import type { DuelRoom } from "./duelConnection.js";
import { renderDuelHud, resultText, type DuelConnectionStatus } from "./duelHud.js";
import { DuelKeyboard } from "./duelKeyboard.js";

/** The client ticks this often: far finer than a frame, and independent of the display's refresh rate. */
const TICK_MS = 4;
/** The HUD is redrawn this often. */
const HUD_MS = 50;

const { rules } = defaultDuelConfig.moveset;

/**
 * One browser's duel: the room's messages feed a `DuelClientSession` (the same rollback core the headless test
 * client runs), a 4 ms timer ticks it with the keyboard's input and sends what it returns, the arena draws the
 * predicted state, and the HUD shows the confirmed one. `window.__duel` exposes read-only diagnostics for tests.
 */
export class DuelClient implements ArenaSource {
  private session: DuelClientSession | undefined;
  private status: DuelConnectionStatus = "connected";
  private boxes = false;
  private readonly keyboard: DuelKeyboard;
  private readonly timers: number[] = [];
  private readonly pendingEvents: DuelFeedEvent[] = [];

  constructor(
    private readonly room: DuelRoom,
    private readonly hud: HTMLElement,
  ) {
    this.keyboard = new DuelKeyboard(window);
    room.onMessage(DuelMessageType.Probe, (message: unknown) => {
      const probe = duelProbeSchema.safeParse(message);
      if (!probe.success) return;
      room.send(DuelMessageType.Probe, { id: probe.data.id } satisfies DuelProbeReply);
      this.ensureSession()?.receiveProbe(probe.data, performance.now());
    });
    room.onMessage(DuelMessageType.Frames, (message: unknown) => {
      const bundle = duelFrameBundleSchema.safeParse(message);
      if (bundle.success) this.ensureSession()?.receiveBundle(bundle.data, performance.now());
    });
    room.onDrop(() => {
      this.status = "reconnecting";
    });
    room.onReconnect(() => {
      this.status = "connected";
    });
    room.onLeave(() => {
      this.status = "disconnected";
      this.renderHud();
      for (const timer of this.timers) window.clearInterval(timer);
    });
    this.timers.push(window.setInterval(() => this.tick(), TICK_MS));
    this.timers.push(window.setInterval(() => this.renderHud(), HUD_MS));
    (window as unknown as { __duel: unknown }).__duel = {
      stats: () => this.session?.stats,
      frame: () => this.session?.frame,
      confirmedFrame: () => this.session?.rollback.confirmedFrame,
      lastTaggedFrame: () => this.session?.lastTaggedFrame,
      /** The input bits this client tagged for frames `from` to `to` (0 where none was). */
      taggedInputs: (from: number, to: number) =>
        Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => this.session?.rollback.localInput(from + index) ?? 0),
    };
  }

  /** The developer toggle for hurtboxes and hitboxes. */
  setShowBoxes(show: boolean): void {
    this.boxes = show;
  }

  /** Practice rooms: the dummy idles or guards. */
  setDummy(dummy: DummyBehaviour): void {
    this.room.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
  }

  state(): DuelState | undefined {
    return this.session?.state;
  }

  drainEvents(): DuelFeedEvent[] {
    this.collectEvents();
    return this.pendingEvents.splice(0);
  }

  stateAt(frame: number): DuelState | undefined {
    return this.session?.rollback.stateAt(frame);
  }

  showBoxes(): boolean {
    return this.boxes;
  }

  banner(): string {
    const state = this.room.state;
    if (state === undefined) return "";
    if (state.phase === "waiting") return state.practice ? "" : "Waiting for an opponent";
    if (state.phase === "countdown") return String(Math.max(1, Math.ceil(state.countdown / 60)));
    if (state.phase === "over") return resultText(state.winner, state.reason);
    return (this.session?.frame ?? 0) < 45 ? "FIGHT" : "";
  }

  private get self(): PlayerIndex | undefined {
    const seat = this.room.state?.seats?.find((entry) => entry.sessionId === this.room.sessionId);
    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
  }

  private ensureSession(): DuelClientSession | undefined {
    if (this.session !== undefined) return this.session;
    const self = this.self;
    const seed = this.room.state?.seed;
    if (self === undefined || seed === undefined) return undefined;
    this.session = new DuelClientSession({ config: defaultDuelConfig, player: self, initial: createDuelState(defaultDuelConfig, { seed }) });
    return this.session;
  }

  private tick(): void {
    const session = this.ensureSession();
    // Once the result is in, nothing the player presses matters any more.
    if (session === undefined || this.room.state?.phase === "over") return;
    const delay = this.room.state?.inputDelay ?? 0;
    if (delay > 0) session.inputDelay = delay;
    const tagged = session.lastTaggedFrame;
    const message = session.tick(performance.now(), this.keyboard.bits());
    if (session.lastTaggedFrame > tagged) this.keyboard.framesTagged();
    if (message !== undefined) this.room.send(DuelMessageType.Input, message);
    this.collectEvents();
  }

  /** Events are drained every tick, so none is lost while the arena is not drawing (a hidden tab). */
  private collectEvents(): void {
    const fresh = this.session?.drainEvents() ?? [];
    this.pendingEvents.push(...fresh);
    if (this.pendingEvents.length > 32) this.pendingEvents.splice(0, this.pendingEvents.length - 32);
  }

  private renderHud(): void {
    const state = this.room.state;
    const self = this.self;
    if (state === undefined || self === undefined) return;
    const session = this.ensureSession();
    const connected = [0, 1].map((slot) => state.seats.find((seat) => seat.slot === slot)?.connected ?? false) as [boolean, boolean];
    renderDuelHud(this.hud, {
      code: state.code,
      practice: state.practice,
      phase: state.phase as DuelRoomPhase,
      status: this.status,
      self,
      countdown: state.countdown,
      connected,
      confirmed: session?.confirmedState ?? createDuelState(defaultDuelConfig, { seed: state.seed }),
      maxHealth: rules.maxHealth,
      maxStamina: rules.maxStamina,
      roundFrames: rules.roundFrames,
      overtimeFrames: rules.overtimeFrames,
      rttMs: session?.rttMs ?? 0,
      inputDelay: state.inputDelay,
      corrections: session?.stats.corrections ?? 0,
      result: state.phase === "over" ? { winner: state.winner, reason: state.reason } : undefined,
    });
  }
}
import type { DuelRoomPhase } from "@pirate-sea-race/protocol";
import type { DuelState, PlayerIndex } from "@pirate-sea-race/simulation/duel";

export type DuelConnectionStatus = "connected" | "reconnecting" | "disconnected";

export interface DuelHudModel {
  readonly code: string;
  readonly practice: boolean;
  readonly phase: DuelRoomPhase;
  readonly status: DuelConnectionStatus;
  /** This browser's player, 0 or 1. */
  readonly self: PlayerIndex;
  /** Frames left in the countdown. */
  readonly countdown: number;
  /** Seats connected, by player. */
  readonly connected: readonly [boolean, boolean];
  /** The newest state stepped from the server's confirmed inputs: the authoritative health, stamina and clock. */
  readonly confirmed: DuelState;
  readonly maxHealth: number;
  readonly maxStamina: number;
  readonly roundFrames: number;
  readonly overtimeFrames: number;
  readonly rttMs: number;
  readonly inputDelay: number;
  readonly corrections: number;
  readonly result: { readonly winner: number; readonly reason: string } | undefined;
}

function field(root: ParentNode, id: string): HTMLElement {
  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  if (element === null) throw new Error(`missing duel HUD field ${id}`);
  return element;
}

/**
 * The round clock in whole seconds (§7: 60 seconds, then 10 of overtime on equal health). It reads 0 on the round's
 * last frame, where a timeout is decided; overtime starts on the frame after.
 */
export function roundClock(frame: number, roundFrames: number, overtimeFrames: number): { seconds: number; overtime: boolean } {
  if (frame <= roundFrames) return { seconds: Math.ceil((roundFrames - frame) / 60), overtime: false };
  return { seconds: Math.max(0, Math.ceil((roundFrames + overtimeFrames - frame) / 60)), overtime: true };
}

const REASONS: Record<string, string> = {
  ko: "KO",
  "double-ko": "double KO",
  timeout: "time",
  overtime: "overtime",
  forfeit: "forfeit",
};

/** "Player 1 wins by KO", "Draw by double KO". */
export function resultText(winner: number, reason: string): string {
  const how = REASONS[reason] ?? reason;
  return winner < 0 ? `Draw (${how})` : `Player ${winner + 1} wins by ${how}`;
}

function playerName(model: DuelHudModel, player: PlayerIndex): string {
  if (player === model.self) return `Player ${player + 1} (you)`;
  return model.practice ? `Player ${player + 1} (dummy)` : `Player ${player + 1}`;
}

/**
 * The duel HUD (§13): both health bars and stamina, the round clock and the connection line, all from the confirmed
 * (server-equal) state, then the result. Data attributes carry the exact numbers for the browser tests.
 */
export function renderDuelHud(root: ParentNode, model: DuelHudModel): void {
  field(root, "duel-code").textContent = model.practice ? `${model.code} (practice)` : model.code;
  field(root, "duel-status").textContent = model.status;
  const phase = field(root, "duel-phase");
  phase.textContent = model.phase === "countdown" ? `Fight in ${Math.ceil(model.countdown / 60)}` : model.phase;
  phase.dataset["phase"] = model.phase;

  for (const player of [0, 1] as const) {
    const fighter = model.confirmed.fighters[player];
    field(root, `duel-name-${player}`).textContent = `${playerName(model, player)}${model.practice && player === 1 ? "" : model.connected[player] ? "" : " (away)"}`;
    const health = field(root, `duel-health-${player}`);
    health.dataset["value"] = String(fighter.health);
    health.style.setProperty("--fill", `${(100 * fighter.health) / model.maxHealth}%`);
    field(root, `duel-health-text-${player}`).textContent = `${fighter.health} / ${model.maxHealth}`;
    const stamina = field(root, `duel-stamina-${player}`);
    stamina.dataset["value"] = String(fighter.stamina);
    stamina.style.setProperty("--fill", `${(100 * fighter.stamina) / model.maxStamina}%`);
  }

  const clock = roundClock(model.confirmed.frame, model.roundFrames, model.overtimeFrames);
  const clockField = field(root, "duel-clock");
  clockField.textContent = clock.overtime ? `OT ${clock.seconds}` : String(clock.seconds);
  clockField.dataset["frame"] = String(model.confirmed.frame);
  clockField.dataset["seconds"] = String(clock.seconds);

  field(root, "duel-rtt").textContent = `${Math.round(model.rttMs)} ms`;
  field(root, "duel-delay").textContent = model.inputDelay > 0 ? `${model.inputDelay} frames` : "measuring";
  field(root, "duel-delay").dataset["frames"] = String(model.inputDelay);
  field(root, "duel-corrections").textContent = String(model.corrections);
  field(root, "duel-corrections").dataset["count"] = String(model.corrections);

  const result = field(root, "duel-result");
  result.hidden = model.result === undefined;
  if (model.result !== undefined) {
    field(root, "duel-result-text").textContent = resultText(model.result.winner, model.result.reason);
    result.dataset["winner"] = String(model.result.winner);
    result.dataset["reason"] = model.result.reason;
    result.dataset["frame"] = String(model.confirmed.frame);
    result.dataset["health"] = model.confirmed.fighters.map((fighter) => fighter.health).join(",");
  }
}

